#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=12

SPIKE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ENV_FILE="$SPIKE_DIR/.env"
umask 077
CONSOLE="https://console.cloud.google.com"
DEVCONSOLE="https://console.developers.google.com"   # the host Google's Auth platform docs link to

helper() { python3 -I "$SPIKE_DIR/gmail_spike.py" "$@"; }

# check ARGS… runs a helper check until it passes or the person moves on.
# Exit 3 means an earlier stage hasn't finished: stop, since nothing after it can run.
check() {
  local rc
  while :; do
    rc=0; helper "$@" || rc=$?
    (( rc == 0 )) && return 0
    if (( rc == 3 )); then trap - EXIT; exit 1; fi
    confirm "Run that again?" || { warn "Moving on; what's above is recorded as it is."; return 0; }
  done
}

# ask_required KEY PROMPT [secret] asks until the answer isn't empty.
ask_required() {
  while :; do
    if [[ "${3:-}" == secret ]]; then ask_secret "$1" "$2"; else ask "$1" "$2"; fi
    [[ -n "${!1}" ]] && return 0
    warn "This one can't be empty."
  done
}

# observe TITLE PROMPT records what the person saw, in their own words.
observe() {
  local obs=""
  printf '  %s%s%s ' "$BOLD" "$2" "$RESET"
  read -r obs || true
  helper note --title "$1" --text "$obs" >/dev/null
  printf '  %s✓ noted%s\n' "$GREEN" "$RESET"
}

s1() {
  stage "Signup mailbox: a new Gmail kept only for Registrations"
  say "Every Registration will use this address (ADR 0003), so pick a neutral name."
  open_url "https://accounts.google.com/signin"
  step "Create account → personal use. Pick or type the new Gmail address, a username"
  say  "  and a password (keep it in your password manager) → Next."
  step "Google may ask for a phone number to verify. Finish the remaining steps → Next."
  step "Then add it to Gmail on the iPhone: Profile icon (top right, in the search bar)"
  say  "  → Add another account → Google → follow the steps."
  ask_required SIGNUP_ADDRESS "The new address (name@gmail.com):"
  [[ "$SIGNUP_ADDRESS" == *@gmail.com ]] || warn "That isn't a gmail.com address; the checks assume one."
  write_env SIGNUP_ADDRESS "$SIGNUP_ADDRESS"
  pause "Enter for the next stage"
}

s2() {
  stage "Google Cloud: a throwaway project with the Gmail API"
  say "Sign in as the Signup mailbox, so the throwaway client lives in that account."
  open_url "$CONSOLE/projectcreate"
  step "Accept the Google Cloud terms if asked. Skip any free-trial or billing offer:"
  say  "  a project needs no billing account, and card details are a Hard limit."
  step "Project name: lab1-gmail-spike. Leave Parent resource as it is → Create."
  note "The console makes a Project ID from the name; it shows in the New project form."
  ask_required GCP_PROJECT_ID "Project ID:"
  write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
  open_url "$CONSOLE/apis/library/gmail.googleapis.com?project=$GCP_PROJECT_ID"
  note "If the link lands elsewhere: Menu → APIs & Services → Library → Gmail API."
  step "Click Enable."
  pause "Enter once the Gmail API shows as enabled"
}

s3() {
  stage "Google Auth Platform: get started"
  open_url "$DEVCONSOLE/auth/branding?project=$GCP_PROJECT_ID"
  note "If the link lands elsewhere: Menu → Google Auth platform → Branding."
  step "\"Google Auth platform not configured yet\" → Get Started."
  step "App Information: App name lab1-gmail-spike; User support email: the Signup mailbox → Next."
  step "Audience: External → Next."
  step "Contact Information: the Signup mailbox → Next."
  step "Finish: tick the Google API Services User Data Policy agreement → Continue → Create."
  note "Leave Test users for the next stage."
  pause "Enter once it's created"
}

s4() {
  stage "Google Auth Platform: the two Gmail scopes, and a test user"
  open_url "$DEVCONSOLE/auth/scopes?project=$GCP_PROJECT_ID"
  note "If the link lands elsewhere: Menu → Google Auth platform → Data Access."
  step "ADD OR REMOVE SCOPES → tick these two in the list (or paste them into the box"
  say  "  under Manually add scopes) → UPDATE:"
  say  "    https://www.googleapis.com/auth/gmail.readonly"
  say  "    https://www.googleapis.com/auth/gmail.compose"
  step "Both should now sit in the table as restricted scopes. If a Save button shows, click it."
  open_url "$DEVCONSOLE/auth/audience?project=$GCP_PROJECT_ID"
  step "Leave Publishing status at Testing: publishing needs Branding links we don't have yet."
  step "Under Test users → Add users → $SIGNUP_ADDRESS → Save."
  note "Without this, consent ends in \"Access blocked … Error 403: access_denied\"."
  observe "Audience" "What does the Audience page show now (status, test users)?"
  pause "Enter for the next stage"
}

s5() {
  stage "OAuth client: Desktop app"
  open_url "$DEVCONSOLE/auth/clients?project=$GCP_PROJECT_ID"
  note "If the link lands elsewhere: Menu → Google Auth platform → Clients."
  step "Create Client → Application type: Desktop app → Name: lab1-gmail-spike → Create."
  note "Already made one? Open it from the list instead, and use that client's ID and secret."
  warn "Google shows the full client secret only once, when it's made. Copy it before closing."
  note "Secret lost or doubtful? On the client's page: Add secret, then copy the new one."
  ask_required CLIENT_ID "Client ID (ends .apps.googleusercontent.com):"
  [[ "$CLIENT_ID" == *.apps.googleusercontent.com ]] || warn "That doesn't look like a client ID."
  write_env CLIENT_ID "$CLIENT_ID"
  while :; do
    ask_required CLIENT_SECRET "Client secret (hidden as you paste):" secret
    CLIENT_SECRET="${CLIENT_SECRET//[[:space:]]/}"
    write_env CLIENT_SECRET "$CLIENT_SECRET"
    helper check-client && break
    warn "Paste the secret of this same client. Can't see it any more? Its page → Add secret."
  done
  pause "Enter for the next stage"
}

s6() {
  stage "Consent: grant gmail.readonly + gmail.compose"
  say "No tunnel needed: you copy one address from the browser and paste it here."
  step "Open the link below in a browser signed in as $SIGNUP_ADDRESS (iPhone or computer)."
  note "If the link breaks across lines when you copy it, the helper rejoins what you paste back."
  step "Google warns the app is unverified: continue past it (Continue, or Advanced → Go to"
  say  "  lab1-gmail-spike), and note what you actually see."
  note "\"Access blocked … access_denied\"? The address isn't a test user yet (stage 4)."
  step "Tick both Gmail permissions → Continue."
  step "The browser then fails to load a 127.0.0.1 page. That's expected: tap or click the"
  say  "  address bar, copy the whole address, paste it below, press Enter."
  check consent
  observe "What consent looked like" "What did you see (the warning, the way past it, checkboxes), and on which device?"
  pause "Enter for the next stage"
}

s7() {
  stage "Test mail and its Authentication-Results"
  step "From your everyday address, mail $SIGNUP_ADDRESS with the subject: wayfinder test 1"
  note "Any body. Keep the mail; the next stages reply to it."
  check wait-mail --key test1 --subject "wayfinder test 1"
  local rc=0
  helper auth-results --key test1 || rc=$?
  if (( rc == 3 )); then trap - EXIT; exit 1; fi
  (( rc == 0 )) || warn "No Authentication-Results header: that's a finding, and it's recorded."
  pause "Enter for the next stage"
}

s8() {
  stage "Reply draft: edit it in Gmail iOS without sending"
  helper make-draft --key test1
  step "In Gmail iOS (Signup mailbox), open the 'wayfinder test 1' conversation."
  say  "  Note whether the draft shows inside it."
  step "Open the draft (in the conversation, or Menu → Drafts) and change the line"
  say  "  \"Edit this line on the iPhone.\" to anything you like."
  step "Don't send: leave the draft with the back arrow. If Gmail asks, keep it as a draft."
  pause "Enter once you've backed out"
  check check-draft
  observe "Reply draft in Gmail iOS" "Did the draft show in the conversation, open as a reply, and save cleanly? Anything odd?"
  pause "Enter for the next stage"
}

s9() {
  stage "Reply draft: send it from Gmail iOS"
  step "Open the draft again in Gmail iOS and tap Send."
  step "In your everyday mailbox, the reply should land inside the 'wayfinder test 1' conversation."
  pause "Enter once it's sent"
  check check-sent
  observe "Reply draft sent from Gmail iOS" "Did it send cleanly, and arrive threaded at your everyday address?"
  pause "Enter for the next stage"
}

s10() {
  stage "Optional: does a plus-address From survive an API send?"
  say "This really sends one mail through the Gmail API, from <signup>+wayfinder@gmail.com"
  say "to your everyday address. Nothing depends on it: Reply drafts go from the plain address."
  if confirm "Send it?"; then
    helper plus-send
    step "In your everyday mailbox, open 'wayfinder plus-address From test' and look at the sender."
    observe "Plus-address From, as received" "Which From address did your everyday mailbox show?"
  else
    helper note --title "Plus-address From on an API send" --text "Skipped" >/dev/null
  fi
  pause "Enter for the next stage"
}

s11() {
  stage "Spam: does history.list report mail that lands in Spam?"
  helper checkpoint --name spam
  step "In Gmail iOS (Signup mailbox), open 'wayfinder test 1' → More (top right, next to"
  say  "  Reply) → Block \"<you>\". Gmail then files your everyday address's mail in Spam."
  step "From your everyday address, mail $SIGNUP_ADDRESS with the subject: wayfinder test 2"
  check spam-check --subject "wayfinder test 2" --since spam
  step "Now unblock: Menu → Spam → open 'wayfinder test 2' → More → Unblock."
  pause "Enter once unblocked"
}

s12() {
  stage "Token: refresh it now"
  check refresh
  say "This token comes from a Testing app, so Google expires it 7 days after consent."
  say "The day-8 check needs a published app; publishing waits on the Branding links,"
  say "so no cron job is installed now. Once the app is published, run:"
  say "    python3 -I $SPIKE_DIR/gmail_spike.py consent"
  say "    python3 -I $SPIKE_DIR/gmail_spike.py install-cron"
  helper note --title "Day-8 check" --text "Not scheduled: the app is still in Testing (publishing needs Branding links), so this token expires 7 days after consent. After publishing: consent again, then install-cron." >/dev/null
  helper note --title "Where the throwaway client lives" --text "Google Cloud project $GCP_PROJECT_ID, owned by the Signup mailbox ($CONSOLE/home/dashboard?project=$GCP_PROJECT_ID); .env and token.json in $SPIKE_DIR. To delete: $CONSOLE/iam-admin/settings?project=$GCP_PROJECT_ID → Shut down, then remove its access at https://myaccount.google.com/connections and delete $SPIKE_DIR." >/dev/null
  pause "Enter to finish"
}

if [[ ! -t 0 ]]; then
  printf '  This wizard needs your keyboard: run it in your own terminal, not with ! in Claude Code.\n' >&2
  exit 2
fi

SIGNUP_ADDRESS=$(_existing SIGNUP_ADDRESS || true)
GCP_PROJECT_ID=$(_existing GCP_PROJECT_ID || true)
FROM="${1:-1}"
if ! [[ "$FROM" =~ ^[0-9]+$ ]] || (( FROM < 1 || FROM > TOTAL_STAGES )); then
  printf 'usage: %s [stage 1-%s to resume from]\n' "$0" "$TOTAL_STAGES" >&2
  exit 2
fi

banner "Gmail checks for the Signup mailbox"
_STAGE_INDEX=$((FROM - 1))
trap 'printf "\n"; warn "Stopped in stage $(( _STAGE_INDEX > 0 ? _STAGE_INDEX : 1 )). Resume there with: bash $0 $(( _STAGE_INDEX > 0 ? _STAGE_INDEX : 1 ))"' EXIT
for ((i = FROM; i <= TOTAL_STAGES; i++)); do "s$i"; done
trap - EXIT

finish
say "Results, with no Secrets in them: $SPIKE_DIR/results.md"
say "Go back to Claude Code and say it's done."
